class Jornalista implements Observador {
    public void atualizar(String n) {
        System.out.println("Jornalista: A notícia agora é: " + n);
    }
}

public class Main {
    public static void main(String[] args) {
        CanaisDeNoticias canais = new CanaisDeNoticias();
        Jornalista jornalista = new Jornalista();
